from pathlib import Path
import json
B=Path(__file__).resolve().parent;f=B/'content.json';D=json.loads(f.read_text());R={r['id']:r for r in D['results']};I=[]
def add(id,title,en_title,cat,pages,formula,zh,en,impact,enimpact,results,status='proof_error_repaired'):
 x=dict(id=id,paper_id=D['paper_id'],title=title,category=cat,source_refs=[dict(source_id='src-icml2023-harsanyinet-formal',version_id='ver-icml2023-harsanyinet-formal',pdf_pages=pages)],original_formula_tex=formula,evidence_md=zh,impact_md=impact,text_md=zh+'\n\n'+impact,related_result_ids=results,original_statement_status='counterexample_verified' if cat=='statement_counterexample' else 'source_scope_checked',user_confirmation='not_individually_reviewed',user_review_status='pending',fix_authorization='proof_only_granted',statement_fix_authorization='not_granted',status=status,agent_evidence_status='pdf_and_formula_checked',translations={'en':dict(title=en_title,evidence_md=en,impact_md=enimpact,text_md=en+'\n\n'+enimpact)})
 I.append(x)
 for r in results:R[r]['related_issue_ids'].append(id)
add('hnet-issue-empty-field','Lemma 1 的空场命题反例','Empty-field counterexample to Lemma 1','statement_counterexample',[3,14,15],r'J_j(R_j)=z_j(x)',
 r'原Lemma只要求R1/R2。取 $R_j=\varnothing,z_j\equiv1$，R1成立且R2为空积1。但原Definition2使所有中心化交互零，尤其 $J_j(\varnothing)=0\ne1$。PDF15推导非空集合交替和为零时未分辨空场。',r'The original lemma assumes only R1/R2. An empty-field unit constantly equal to one satisfies both requirements, including the empty product in R2. Definition 2 makes every centered dividend zero, so the claimed field dividend differs from its unit value. The page-15 alternating-sum argument fails to separate the empty field.',
 '原Lemma全范围错误，不能加非空前提；实际无偏置架构零基线子结论另证。Theorem3只分给包含玩家的场，常数单元贡献零，并未被此反例推翻。','The full lemma is false and cannot be repaired by adding a nonempty premise. The bias-free architecture boundary is proved separately. Theorem 3 allocates only fields containing a player and gives constant units zero, so this counterexample does not refute its valid algorithm.', ['hnet-unit-interaction'], 'statement_error_unrepaired')
add('hnet-issue-t3-empty-division','Theorem 3 原全j分式空场约定未明','Theorem 3 lacks a printed empty-field division convention','expression_domain',[12,13],r'\sum_j\frac{w_jz_j(x)}{|R_j|}\mathbf1_{i\in R_j}',
 '全j求和可能包含空场；实数域先算分式再乘零需要除零约定。严谨条件和只在场含i时算分式，含i保证基数正。','The all-unit sum may contain empty fields. Evaluating the fraction before multiplying a zero indicator requires a division convention. The conditional sum evaluates it only for a field containing the player, whose cardinality is positive.',
 '这是表达式定义域歧义；完整经典归因条件和恒等式已证，不宣称Theorem3被空场Lemma反例推翻。','This is an expression-domain ambiguity. The classical conditional-sum identity is proved; the empty-field lemma counterexample is not presented as a refutation of that identity.', ['hnet-forward-shapley'],'scope_ambiguous')
add('hnet-issue-t4-quantifier','Theorem 4 证明的全第一层量词及乘积替换错误','Incorrect first-layer quantifier and product substitution in Theorem 4','proof_step_error',[13,14],r'\forall u^{\prime},\ z_{u^{\prime}}^{(1)}(x_T)=0',
 '缺一个输入变量只保证依赖它的孩子沿路径为零，不保证所有第一层节点为零。整个AND积也不能无条件等于指定单因子；修正只使用存在一个零因子使乘积零。','Missing one input only makes relevant dependent children vanish, not every first-layer neuron. An entire AND product also cannot be replaced unconditionally by one factor. The repair uses one zero factor to make the product zero.',
 '命题不变，按感受野并集和拓扑次序证明R1/R2；完整原链保留在original-proofs。','The proposition is unchanged. The repaired proof follows field unions and feed-forward induction; the full printed chain remains in original-proofs.', ['hnet-architecture-r1-r2'])
add('hnet-issue-cnn-filter','CNN 原交互展开漏感受野过滤','Missing receptive-field filter in the CNN interaction expansion','proof_step_error',[16],r'I(S=R_u)=\sum_jw_jz_j(x)',
 r'目标S固定时只有 $R_j=S$ 的单元贡献。场分别为单例1/2、贡献各1时，目标单例1的交互1而无过滤末和2。原等式全文保留，修正加入已由unit变换导出的过滤。',r'For a fixed target, only units with that field contribute. Two distinct singleton-field units with contribution one each give target dividend one but an unfiltered final sum two. The printed equality is preserved; its repair restores the filter derived from the unit transform.',
 '不否定正确有限通道重组；修正同一模型的目标交互展开。','This repairs the target-dividend expansion for a single model and does not refute finite channel regrouping.', ['hnet-cnn-regroup'])
add('hnet-issue-cnn-activation','共同gate不推出全部通道输出同时非零','A common gate does not force simultaneous nonzero channel outputs','proof_step_error',[16],r'h_{(1,h,w)},\ldots,h_{(C,h,w)}\text{ activate simultaneously}',
 '原句用共同孩子推出同时激活。共同gate确相同，但两个权重给线性值1与-1，ReLU后为(1,0)。因此只能说gate同时开闭，不能把非零输出同步当作group证明前提。','The printed sentence infers simultaneous activation from shared children. The common gate agrees, but weights producing preactivations one and minus one give post-ReLU outputs (1,0). Only the gate states agree; simultaneous nonzero output cannot be used in the grouped proof.',
 '感受野等式及加权有限和仍成立；分组gate掩码律独立证明。','The field equality and weighted finite regrouping remain valid. The grouped gate’s mask law is proved independently.', ['hnet-cnn-receptive','hnet-cnn-regroup'])
add('hnet-issue-cnn-gate-equivalence','scalar AND 与 group gate 数值等价子句错误','False numerical-equivalence subclaim for scalar AND and grouped gates','statement_counterexample',[7,16],r'\prod_c\mathbf1_{z_c\ne0}=\mathbf1_{\sum_c|z_c|\ne0}',
 '孩子向量(1,0)给左gate0、右gate1；父线性值1时ReLU输出分别0、1。改变gate没有保持同一函数。','A child vector (1,0) gives scalar gate zero and grouped gate one. With parent linear value one, the outputs are zero and one. Changing the gate therefore changes the function.',
 '仅此数值等价子句被否定；新groupgate架构仍能满足R1/R2及其自身输出的Shapley式，正文完整直接归纳。','Only this numerical-equivalence subclaim is refuted. The new grouped architecture still satisfies R1/R2 and the Shapley identity for its own output, as shown by the direct induction.', ['hnet-cnn-regroup'],'statement_error_unrepaired')
add('hnet-issue-eq9-baseline','Eq.(9) 任意传统网络省略输出基线','Equation (9) omits the output baseline for general conventional networks','statement_counterexample',[3,6],r'v(x)=\sum_{S\subseteq N}I(S)',
 r'本篇I为中心化交互，重构和是 $v(x)-v(x_\varnothing)$。常数模型1全部I为零但原输出1，反例否定任意传统网络的第一等号。','The paper uses centered dividends, whose sum is the output difference from the baseline. A constant-one model has every centered dividend zero but raw output one, refuting the first equality for an arbitrary conventional model.',
 '无偏置Harsanyi实际架构基线零时成立；M数量界不证明传统DNN尾和小。','The equality holds for the actual bias-free Harsanyi architecture with zero baseline. The M-count bound does not prove small omitted effects in a conventional DNN.', ['hnet-sparsity-count','hnet-external-sparsity'],'statement_error_unrepaired')
add('hnet-issue-smooth-domain','光滑gate空选子指数与第一层非负域未说明','Unspecified empty selection and first-layer domain for the smooth gate','expression_domain',[5,6],r'1/\operatorname{tr}\Sigma_j',
 '空选子使trace为零，几何均值指数无实数定义约定。第一层x-r未经ReLU，可为负，不能自动套所有前层非负的说明。','An empty child selection has zero trace, leaving the geometric-mean exponent without a real-domain convention. First-layer centered inputs precede ReLU and can be negative, so the nonnegative-child description does not automatically include them.',
 '完整记录训练定义及边界；hardgate形式化不冒充该训练公式全参数域验证。','The training definition and its boundaries are recorded completely. Hard-gate verification is not presented as verification of this formula over its entire parameter domain.', ['hnet-smooth-gate'],'domain_unspecified')
for r in D['results']:r['related_issue_ids']=list(dict.fromkeys(r['related_issue_ids']))
D['issues']=I
(B/'issues.json').write_text(json.dumps(dict(paper_id=D['paper_id'],issues=I),ensure_ascii=False,indent=2)+'\n');f.write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n')
print('Hnet issues',len(I))
